// Duotone-Neon: Helligkeit auf zwei Neonfarben abgebildet; der Farbton
// wandert langsam mit der Zeit, Hoehen hellen die Lichter auf.
vec4 farbe(vec2 uv, vec4 src)
{
    float hell = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    float drift = 0.5 + 0.5 * sin(uTime * 0.15);
    vec3 dunkelA = vec3(0.10, 0.02, 0.35);
    vec3 dunkelB = vec3(0.00, 0.15, 0.30);
    vec3 hellA = vec3(1.00, 0.25, 0.55);
    vec3 hellB = vec3(0.20, 0.95, 0.85);
    vec3 dunkel = mix(dunkelA, dunkelB, drift);
    vec3 licht = mix(hellA, hellB, drift);
    vec3 farbe = mix(dunkel, licht, smoothstep(0.05, 0.95, hell));
    farbe += treb * 0.25 * smoothstep(0.7, 1.0, hell);
    return vec4(clamp(farbe, 0.0, 1.0), 1.0);
}
